fn remove_duplicates(nums: &Vec<i32>) -> usize {
    if nums.is_empty() {
        return 0;
    }

    let mut count = 1; // At least one unique value if non-empty
    for i in 1..nums.len() {
        if nums[i] != nums[i - 1] {
            count += 1;
        }
    }

    count
}